// High-value lead processing
const leadData = $node['Store Qualified Lead'].json;
const qualification = JSON.parse($node['AI Lead Qualification'].json.choices[0].message.content);

return {
  lead_id: leadData.id,
  priority: 'high',
  action: 'immediate_outreach',
  assigned_to: 'senior_consultant',
  follow_up_hours: 2,
  qualification_score: qualification.qualification_score,
  estimated_value: qualification.estimated_value
};

